  "claims": [
    {
      "claim": "Transferable L1 gold-context records consistently report absolute oral bioavailability at or above 20% in humans and relevant models: apixaban ~50% (C01, C08), pentopril >58–70% (C05, C12, C30, C31), cefroxadine ~100% (C09, C49, C84), and midodrine 93% (C18, C24).",
      "card_ids": ["C01","C05","C08","C09","C12","C18","C24","C30","C31","C49","C84"]
    },
    {
      "claim": "L4/L5 intestinal absorption and permeability records for lipophilic basic amines and a calcium-channel blocker show high absorption/permeability and low or absent efflux: imipramine essentially 100% absorbed with Caco-2 ER 1.1 (C140, C143, C170, C187, C189), promethazine passive ER 1.1 (C149, C195), nicardipine high passive permeability with efflux insignificant (C146, C194, C197), compound 16a Papp A-B 19.9e-6 with ER 0.7 (C222), and asimadoline at least 20% absorbed within 1 h with P-gp not limiting net uptake (C218).",
      "card_ids": ["C140","C143","C146","C149","C170","C187","C189","C194","C195","C197","C218","C222"]
    },
    {
      "claim": "L5 gut-wall records do not provide affirmative threshold-relevant evidence for F<20%; the only metabolism/efflux mechanism records (nicardipine intestinal CYP3A substrate C236; tamoxifen P-gp substrate C210) are mechanism-only and their source molecules have high F in L1 contexts.",
      "card_ids": ["C210","C236"]
    },
    {
      "claim": "The only sub-20% records are species-specific and non-transferable to the human-condition query: tamoxifen 13.15% in horses (C35, C86) and ASV 11% in monkeys (C39); they do not support low F for the query.",
      "card_ids": ["C35","C39","C86"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C189","C194","C195","C197","C210","C218","C222","C236"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No query-specific L5 efflux or intestinal-metabolism record is present; L5 records are for reference molecules.",
    "No matched oral-versus-IV exposure data are available for the query.",
    "First-pass ester hydrolysis and any P-gp/CYP3A contribution for the query are not directly quantified.",
    "Transfer from animal/species-specific low-F records is limited."
  ],
  "decision_summary": "For this benzothiazepine calcium-channel blocker, transferable L1 gold contexts consistently support F>=20%, and L4/L5 intestinal absorption/permeability and efflux records for related lipophilic basic amines and a calcium-channel blocker support high absorption and no significant efflux. The only metabolism/efflux mechanism records are not affirmative low-F evidence. Prediction remains high and is strengthened."
}

